def entrypoint() -> dict:
    system = """You are an expert in evolving HoVer multi-hop fact verification chains.\n\n{task_description}\n\n{metrics_description}\n\nCRITICAL: Steps 3 & 6 must output ONLY BM25 queries (e.g., \"Marie Curie nationality\"). No prose allowed.\nSYSTEM_PROMPT is prepended to 4 steps — keep it short. Third hop (step 6) is hardest."""

    user = """EVOLUTIONARY MUTATION: HoVer Chain\n\n## INTELLIGENCE INPUTS\n{parent_blocks}\n\n## HOVER KNOWLEDGE\n- 3 hops: find all 3 gold articles (one per hop).\n- Step 3 & 6: PURE queries only (no reasoning). Good: \"X Y\", Bad: \"Find X's Y\".\n- Step 5: Combine hop1+hop2 evidence for step 6.\n- System_prompt: 4x context cost — be concise.\n\n## ARCHETYPE SELECTION\nExploitation (strong evidence): \n  1. Precision Optimization (fine-tune)\n  2. Proven Pattern Extension (replicate)\n  3. Harmful Pattern Removal (remove failures)\nExploration (weak evidence):\n  4. Computational Reinvention (novel)\n  5. Solution Space Exploration (new strategies)\n  6. Approach Synthesis (hybrid)\nHybrid (mixed):\n  7. Guided Innovation (preserve + improve)\n  8. Conservative Exploration (safe)\n\n## OUTPUT\nRespond with ONLY JSON having:\n  \"archetype\": (str) one of 1-8\n  \"justification\": (str) 2-3 sentences\n  \"insights_used\": (list[str]) 1-3 insights\n  \"code\": (str) complete Python program\n\nNO MARKDOWN. NO EXTRA TEXT."""

    return {"system": system, "user": user}
